public class CloneMemberProbe {
    public class Leaf {public String text='seed';}
    public virtual class Parent {public String label='seed';public Leaf leaf=new Leaf();}
    public class Child extends Parent {
        public List<String> words=new List<String>{'first'};
        public Map<String,Leaf> entries=new Map<String,Leaf>();
        public Account record=new Account(Name='seed');
        public Child self;
        public Child copy() {return this.clone();}
    }
    public static String observe() {
        Child original=new Child();original.self=original;
        original.entries.put('leaf',original.leaf);
        Child copied=original.copy();
        Map<String,Object> out=new Map<String,Object>();
        out.put('differentRoot',original!==copied);
        out.put('sameLeaf',original.leaf===copied.leaf);
        out.put('sameWords',original.words===copied.words);
        out.put('sameMap',original.entries===copied.entries);
        out.put('sameRecord',original.record===copied.record);
        out.put('selfIsOriginal',copied.self===original);
        copied.label='copy';out.put('originalLabel',original.label);
        original.leaf.text='changed';out.put('copiedLeaf',copied.leaf.text);
        copied.words.add('second');out.put('originalWordCount',original.words.size());
        copied.entries.get('leaf').text='mapChange';out.put('originalLeaf',original.leaf.text);
        copied.record.Name='recordChange';out.put('originalRecordName',original.record.Name);
        copied.leaf=new Leaf();out.put('originalLeafAfterReplace',original.leaf.text);
        out.put('copiedLeafAfterReplace',copied.leaf.text);
        return JSON.serialize(out);
    }
}

